class AnyRunnable {
    struct Concept { virtual void run() = 0; virtual ~Concept() = default; };
    template<typename T> struct Model : Concept {
        T data;
        Model(T x) : data(std::move(x)) {}
        void run() override { data(); }
    };
    std::unique_ptr<Concept> pImpl;
public:
    template<typename T>
    AnyRunnable(T x) : pImpl(std::make_unique<Model<T>>(std::move(x))) {}
    void run() { pImpl->run(); }
};

